"""Package retained numerical results for static, inspectable web viewers.

Run after export_remote.py, export_plume.py and export_battery.py. No solver
is executed. Float32 fields are stored [snapshot, quantity, displayed cell].
"""
from pathlib import Path
import csv,json,shutil,hashlib,sys
import numpy as np
from matplotlib import colormaps
ROOT=Path(__file__).resolve().parents[1];SRC=Path(sys.argv[1]);OUT=ROOT/'assets/studies/explorers';OUT.mkdir(parents=True,exist_ok=True)
def load(p):return json.loads(p.read_text())
def dump(p,x):p.write_text(json.dumps(x,separators=(',',':'),allow_nan=False))
def copy(r,o,names):
 for n in names:shutil.copy2(r/n,o/n)
def rows(p):return list(csv.DictReader(p.open()))
def history(data,time,specs):return {'time':[float(x) for x in data[time]],'series':[dict(key=k,label=l,unit=u,values=[float(x) for x in data[k]]) for k,l,u in specs]}
def histrows(rs,specs):return history({k:[r[k] for r in rs] for k in rs[0]},'time_s',specs)
palette=(colormaps['viridis'](np.linspace(0,1,256))[:,:3]*255).round().astype(int).tolist()
# Native OpenFOAM cell values on the original planar mesh.
r=SRC/'plume';o=OUT/'plume';o.mkdir(exist_ok=True);x=load(r/'export.json');metrics=load(r/'cell_metrics.json')
cfg={'id':'plume','title':'Aircraft exhaust · native gas fields','mode':'cells','snapshots':[{'time':t,'phase':('Release' if t<=10 else 'Dispersion')} for t in x['times']], 'views':[{'id':'section','label':'Center-plane gas domain · X/Y','polygons':x['polygons'],'file':'fields.bin','axis_labels':['X / m','Y / m'],'bounds':[-3,14,0,8]}], 'variables':[{'key':'temperature','label':'Gas temperature','unit':'°C','range':[25,600]},{'key':'speed','label':'Gas speed','unit':'m/s','range':[0,45]}], 'history':histrows(metrics,[('max_cell_temperature_C','Hottest gas cell','°C'),('max_near_ground_cell_temperature_C','Near-ground gas peak','°C'),('max_cell_speed_m_s','Fastest gas cell','m/s'),('hot_area_above_60C_m2','Gas area above 60°C','m²')]),'palette':palette,'field_note':'Native cell values on the 13,472-cell 2D gas mesh. The aircraft and ground are boundary surfaces; their solid temperatures were not solved. Display range is fixed; values outside it saturate. Click a cell to plot its saved-time history.','source_note':'R5 native OpenFOAM fields; 0.1 m computational span, 61 snapshots, 0–15 s. A hypothetical, nonreacting release; no mesh/time-step independence or safety qualification.','source_hash':x['cache_sha256'],'default_index':24}
copy(r,o,['fields.bin','run_summary.json','cell_metrics.json','geometry.json','geometry_validation.json','prepare_cfd.py','README.md','center_section_with_vent.step','midnight_center_section.FCStd']);dump(o/'viewer.json',cfg)
# A real FE section; maintain the original material labels. Triangle means
# are derived from linear FE point interpolation, not full-volume maxima.
r=SRC/'battery';o=OUT/'battery';o.mkdir(exist_ok=True);x=load(r/'export.json');v=x['views'][0];n=len(v['polygons']);a=np.fromfile(r/'section.bin',dtype='<f4').reshape(len(x['times']),1,n);a.tofile(o/'fields.bin')
labels={1:'Equivalent battery block',2:'Titanium casing',3:'Upper TIM',4:'Lower TIM',5:'Upper cold plate',6:'Lower cold plate',7:'Coolant'}
cfg={'id':'battery','title':'Battery cooling · finite-element section','mode':'cells','snapshots':[{'time':t,'phase':'300 W heating / series cooling'} for t in x['times']], 'views':[{'id':'section','label':v['label'],'polygons':v['polygons'],'components':v['components'],'component_labels':labels,'file':'fields.bin','axis_labels':v['axis_labels']}], 'variables':[{'key':'temperature','label':'Section temperature','unit':'°C','range':[25,65]},{'key':'temperature-detail','label':'Coolant / interface detail','unit':'°C','range':[25,30],'field_index':0}], 'quantity_count':1,'history':histrows(rows(r/'thermal_history.csv'),[('battery_max_C','Full-module peak','°C'),('battery_mean_C','Full-module volume mean','°C'),('coolant_after_plate1_C','Coolant after first plate','°C'),('coolant_out_C','Coolant outlet','°C'),('coolant_heat_W','Heat removed by coolant','W'),('stored_energy_J','Assembly stored energy','J')]),'palette':palette,'field_note':'Y = 0 cut through the 3D FE mesh. Each displayed triangle shows the mean of linearly interpolated FE nodal temperatures on that triangle. Section min/max readouts apply only to this cut; use the full-module history for volume results. Select a material to isolate it. The 25–30°C detail range clips warmer materials.','source_note':'Elmer 26.2.1; 2,084,927 tetrahedra, 372,971 nodes, 121 states at 30 s spacing including the initial condition. Assumed equivalent battery properties; transitional flow treated as laminar. Recovered transport velocity differs from original flow by 22.45% in volume-weighted L2 norm. Screening only; no experimental validation.','source_hash':x['render_fields_sha256'],'default_index':120}
copy(r,o,['thermal_history.csv','results_summary.json','simulation_assumptions.json','mesh_validation.json','flow_validation.json','flux_reconstruction.json','MODEL_NOTES.txt','RESULTS.txt','battery_module_elmer.FCStd','battery_module_all.step']);dump(o/'viewer.json',cfg)
# Original planar liquid fraction and velocity magnitude, selected saved times.
r=SRC/'lunar';o=OUT/'lunar';o.mkdir(exist_ok=True);x=load(r/'export.json');names=['Ground fill','Launch','Cutoff + coast','Settle for departure','Pressurize','Earth departure','Translunar coast','Settle for capture','Lunar capture','Lunar orbit','Orbital refill','Settle for descent','Descent braking','Approach + hover','Touchdown','Lunar surface hold','Prepare for liftoff','Liftoff + pitch','Ascent cutoff','Settle for transfer','Raise apolune','Lunar transfer coast','Settle for insertion','Halo insertion','Lunar orbit coast','Rendezvous','Dock + crew transfer','Lander orbital hold','Orion departure context','Return cruise context','Correction context','Separation context','Entry context','Parachute context','Splashdown context']
for s in x['snapshots']:s['phase']=f"{int(s['phase']):02d} · {names[int(s['phase'])-1]}"
h=x['ledger'];h['pressure_kPa']=[v/1000 for v in h['ullage_pressure_0d_Pa']];h['axial_g']=[-v/9.81 for v in h['g_z_m_s2']];h['feed_percent']=[v*100 for v in h['feed_liquid_fraction']]
cfg={'id':'lunar','title':'Lunar tank · liquid fields through 35 windows','mode':'cells','snapshots':x['snapshots'],'views':[{'id':'section','label':'Native 2D tank plane · X/Z','polygons':x['polygons'],'file':'fields.bin','axis_labels':['X / m','Z / m']}], 'variables':[{'key':'alpha','label':'LOX volume fraction','unit':'fraction','range':[0,1]},{'key':'speed','label':'Fluid speed','unit':'m/s','range':[0,max(h['max_U_m_s'])]}], 'history':history(h,'time_s',[('liquid_percent','Liquid inventory','%'),('pressure_kPa','Independent 0D ullage pressure','kPa'),('feed_percent','Outlet liquid fraction','%'),('axial_g','Prescribed axial load','g'),('liquid_balance_error_percent','Liquid balance error','%'),('max_U_m_s','Maximum fluid speed','m/s')]),'palette':palette,'field_note':f"{len(x['snapshots'])} exact saved states selected from {x['native_snapshot_count']:,} native snapshots, up to seven per phase. No time interpolation. Values are native planar cells, not a 3D tank solve. Fraction display saturates tiny numerical overshoots at 0 and 1. Plots retain the full saved ledger; the cursor readout uses its nearest record and reports that timestamp.",'source_note':'Coarse 2D VOF with prescribed mission windows and separate one-way isothermal 0D helium inventory. CFD window time excludes long physical coasts. From phase 29 the simulated tank stays in lunar orbit; Orion return/entry is context, not solved LOX or aerothermal flow. No grid/time-step independence or physical validation.','default_index':6,'source_hashes':x['source_hashes']}
copy(r,o,['fields.bin','ledger.csv','Planar_Mesh.npz']);dump(o/'viewer.json',cfg)
# Retained native-field renders, synchronized to physical-time forces and
# fixed-loop circulation. The image is explicitly a fixed camera view.
r=SRC/'wake';o=OUT/'wake';o.mkdir(exist_ok=True);gamma=load(r/'Circulation_History.json');f=np.genfromtxt(r/'Force_History.csv',delimiter=',',names=True);f=f[(f['time_s']>=.5)&(f['time_s']<=2)]
# Preserve extrema in 400 bins of each force history as well as endpoints.
ix={0,len(f)-1}
for ids in np.array_split(np.arange(len(f)),400):
 if len(ids):
  for k in ['lift_N','drag_N','Fy_N']:ix.update([int(ids[np.argmin(f[k][ids])]),int(ids[np.argmax(f[k][ids])])])
f=f[sorted(ix)];h={k:f[k].tolist() for k in f.dtype.names};h['lift_kN']=(f['lift_N']/1000).tolist();h['drag_kN']=(f['drag_N']/1000).tolist();h['side_kN']=(f['Fy_N']/1000).tolist()
for p in r.glob('frame_*.jpg'):shutil.copy2(p,o/p.name)
snaps=[{'time':g['time_s'],'phase':'Fixed 20° · full-aircraft transient','image':f'frame_{i:04d}.jpg','circulation':g['Gamma_m2_s']} for i,g in enumerate(gamma)]
cfg={'id':'wake','title':'Aircraft wake · physical-time inspection','mode':'images','snapshots':snaps,'history':history(h,'time_s',[('lift_kN','Full-aircraft lift','kN'),('drag_kN','Full-aircraft drag','kN'),('side_kN','Full-aircraft side force','kN')]),'secondary_history':{'time':[g['time_s'] for g in gamma],'series':[{'key':f'gamma{i}','label':label,'unit':'m²/s','values':[g['Gamma_m2_s'][i] for g in gamma]} for i,label in enumerate(['Circulation · X6 left','Circulation · X6 right','Circulation · X10 left','Circulation · X10 right'])]},'field_note':'75 retained native-field renders at fixed camera and angle. Surface color = signed local lift traction, ±1,800 Pa. Q = 500 s⁻² surfaces are colored by speed, 0–65 m/s. Cyan curves are instantaneous streamlines. These are still images of actual fields; this view does not rotate or query the 3D volume.','source_note':f"0.502–1.982 s; post-startup full-aircraft SST URANS. Load plots retain {len(f):,} extrema-preserving records from the high-rate history. Exact CSV remains downloadable. Time-weighted statistics remain on the methods page. Concave-cell contour omissions affect Q visualization. No validated shedding frequency, grid/time-step independence or OEM validation.",'default_index':0}
copy(r,o,['Force_History.csv','Circulation_History.json','Visualization_Validation.json','Study_Parameters.json','Run_Manifest.json']);dump(o/'viewer.json',cfg)
# Every delivered byte is independently checkable.
for d in OUT.iterdir():
 if not d.is_dir():continue
 manifest={'schema':1,'study':d.name,'scientific_qualification':False,'files':{p.name:{'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(d.iterdir()) if p.is_file() and p.name!='manifest.json'}}
 dump(d/'manifest.json',manifest)
 print(d.name, len(manifest['files']),sum(v['bytes'] for v in manifest['files'].values()),flush=True)
